	builders := make([]*RoutingRuleCreate, rv.Len())
	for i := 0; i < rv.Len(); i++ {
		builders[i] = c.Create()
		setFunc(builders[i], i)
	}
	return &RoutingRuleCreateBulk{config: c.config, builders: builders}
